  current_phases jsonb; next_phases jsonb; phase_entry jsonb; lane_entry record;
  phase_index integer; lane_path text[];
BEGIN
  SELECT phases_json INTO STRICT current_phases FROM public.project_business_plans WHERE project_id='p21' FOR UPDATE;
  IF jsonb_array_length(current_phases) <> jsonb_array_length(mapping) THEN RAISE EXCEPTION 'phase count changed'; END IF;
  next_phases := current_phases;
  FOR phase_entry, phase_index IN SELECT value, (ordinality-1)::integer FROM jsonb_array_elements(mapping) WITH ORDINALITY LOOP
    IF current_phases->phase_index->>'id' IS DISTINCT FROM phase_entry->>'id' THEN RAISE EXCEPTION 'phase id changed'; END IF;
    IF current_phases->phase_index->'comparisonTargets' IS NOT NULL AND current_phases->phase_index->'comparisonTargets' IS DISTINCT FROM phase_entry->'comparisonTargets' THEN RAISE EXCEPTION 'comparison targets changed'; END IF;
    next_phases := jsonb_set(next_phases,ARRAY[phase_index::text,'comparisonTargets'],phase_entry->'comparisonTargets',true);
    FOR lane_entry IN SELECT key,value FROM jsonb_each(phase_entry->'lanes') LOOP
      lane_path := ARRAY[phase_index::text,'lanes',lane_entry.key];
      IF current_phases #> (lane_path || ARRAY['activities']) IS DISTINCT FROM lane_entry.value->'activities' THEN RAISE EXCEPTION 'activities changed for phase %, lane %',phase_entry->>'id',lane_entry.key; END IF;
      IF current_phases #> (lane_path || ARRAY['activityRowKeys']) IS NOT NULL AND current_phases #> (lane_path || ARRAY['activityRowKeys']) IS DISTINCT FROM lane_entry.value->'activityRowKeys' THEN RAISE EXCEPTION 'row mapping changed'; END IF;
      next_phases := jsonb_set(next_phases,lane_path || ARRAY['activityRowKeys'],lane_entry.value->'activityRowKeys',true);
    END LOOP;
  END LOOP;
  UPDATE public.project_business_plans SET phases_json=next_phases,
    matrix_note=rtrim(replace(matrix_note,'出口条件は将来の到達目標で、現在の実績ではない。','')),updated_at=now()
    WHERE project_id='p21' AND (phases_json IS DISTINCT FROM next_phases OR matrix_note LIKE '%出口条件は将来の到達目標で、現在の実績ではない。%');
END;
$migration$;
